head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "1234567.12345",
        "col2": "123456789"
    }, {
        "col1": "12345.12345",
        "col2": "12345"
    }];
    dataList1.setJSON(jsonData);
    //gridView1.changeCurrency("col1", "float", "###,###");
    //gridView1.changeCurrency("col2", "number", "###,###");
    //col1 소수점 입력제어(float는 동작하지 않음)
    gridView1.setDataType("col1", "float");
    gridView1.setColumnDisplayFormat("col1", "#,##0.##");
    gridView1.setMaxLength("col1", "7.2");
    //col2 정수 입력제어(number는 정상동작함)
    gridView1.setDataType("col2", "number");
    gridView1.setColumnDisplayFormat("col2", "#,###");
    gridView1.setMaxLength("col2", "7");
    console.log(gridView1.getDataType("col1"));
    console.log(gridView1.getDataType("col2"));
    //debugger;
    //gridView1.setCellInputType(0, "col2", { inputType : "text", options : {dataType:"float", maxlength:"7.2", displayFormat:"#,###.##", applyFormat:"all"} });
    //gridView1.setCellInputType(1, "col2", { inputType : "text", options : {dataType:"float", maxlength:"10.3", displayFormat:"#,###.###", applyFormat:"all"} });
}
scwin.onpageunload = function() {}
scwin.trigger1_onclick = function(e) {
    var options = {};
    //options.fileName= "numberTest3.xlsx";
    options.fileName = "WEFF-636.xls";
    options.type = "1";
    options.useDataFormat = true;
    gridView1.advancedExcelDownload(options);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_cell_0_0').innerText == '1,234,567.12'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    /*	
    	fn01 = function(val, format_val, row, col ) {
    			debugger;
            	if(val == 1000 || val == "1000"){ 
            		return format_val;

            	}else{
            		return val;
            	}    
    	};
    	*/
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
